export const siteConfig = {
  name: "ShiftWise",
  tagline: "Simplify Restaurant Team Management",
  description: "An all-in-one workforce management platform built for the restaurant and hospitality industry.",
  url: "https://shiftwise.io",

  navigation: [
    { label: "Features", href: "features.html" },
    { label: "Pricing", href: "pricing.html" },
    { label: "About", href: "about.html" },
    { label: "Contact", href: "contact.html" },
  ],

  hero: {
    badge: "Trusted by 35,000+ restaurants",
    title: "Your Restaurant Runs Better When Your Team Is in Sync",
    subtitle: "ShiftWise gives restaurant owners and managers the scheduling, communication, and compliance tools they need — all in one platform. Spend less time on admin and more time delighting guests.",
    cta: { text: "Start Your Free Trial", href: "#" },
    secondaryCta: { text: "See How It Works", href: "#how-it-works" },
  },

  features: [
    {
      icon: "Calendar",
      title: "Drag-and-drop scheduling",
      description: "Build and publish weekly schedules with an intuitive visual editor. Auto-fill based on availability and roles."
    },
    {
      icon: "MessageSquare",
      title: "Team messaging",
      description: "Communicate with individuals, shift groups, or your entire staff. No more lost group texts."
    },
    {
      icon: "Shield",
      title: "Labor law compliance alerts",
      description: "Automatic notifications for overtime thresholds, predictive scheduling laws, and mandatory break periods."
    },
    {
      icon: "CreditCard",
      title: "POS integrations",
      description: "Connect with leading point-of-sale systems to align labor costs with real-time sales data."
    },
    {
      icon: "Clock",
      title: "Time clocking",
      description: "GPS-enabled clock-in/clock-out from any mobile device. Eliminate buddy punching with photo verification."
    },
    {
      icon: "BarChart",
      title: "Demand forecasting",
      description: "Predict busy periods and optimize staffing levels to maximize efficiency and minimize labor costs."
    },
  ],

  howItWorks: [
    {
      step: "01",
      title: "Build Your Schedule",
      description: "Use drag-and-drop tools to create optimized weekly schedules in minutes, not hours."
    },
    {
      step: "02",
      title: "Keep Everyone Connected",
      description: "Broadcast shift updates, swap requests, and announcements through built-in team messaging."
    },
    {
      step: "03",
      title: "Stay Compliant Automatically",
      description: "Get real-time alerts for overtime, break violations, and local labor law requirements."
    },
    {
      step: "04",
      title: "Track & Optimize",
      description: "Monitor labor costs, attendance trends, and team performance from a single dashboard."
    },
  ],

  testimonials: [
    {
      quote: "ShiftWise cut our scheduling time from 6 hours to 30 minutes every week. It's been a game-changer for our three-location operation.",
      author: "Maria Gonzalez",
      role: "General Manager",
      company: "Fuego Kitchen"
    },
    {
      quote: "The compliance alerts alone have saved us from costly violations. I sleep better knowing ShiftWise has our back.",
      author: "David Park",
      role: "Owner",
      company: "Noodle Republic"
    },
    {
      quote: "Our staff actually loves it — shift swaps happen in seconds and everyone stays in the loop.",
      author: "Aisha Thompson",
      role: "Operations Director",
      company: "Greenleaf Café Group"
    },
  ],

  stats: [
    { value: "750,000+", label: "Shifts scheduled monthly" },
    { value: "35,000+", label: "Restaurant managers" },
    { value: "98%", label: "Customer satisfaction" },
    { value: "15 hrs/week", label: "Average time saved" },
  ],

  pricing: [
    {
      name: "Free",
      price: { monthly: 0, annual: 0 },
      description: "Perfect for single-location restaurants just getting started.",
      features: [
        { text: "1 location", included: true },
        { text: "Up to 15 employees", included: true },
        { text: "Drag-and-drop scheduling", included: true },
        { text: "Team messaging", included: false },
        { text: "Labor compliance alerts", included: false },
        { text: "POS integrations", included: false },
        { text: "Time clocking", included: false },
        { text: "Demand forecasting", included: false },
        { text: "Dedicated account manager", included: false },
        { text: "Support", included: true, detail: "Email" },
      ],
      cta: "Start Free",
      popular: false,
    },
    {
      name: "Starter",
      price: { monthly: 29.99, annual: 23.99 },
      description: "Ideal for growing restaurants with up to 3 locations.",
      features: [
        { text: "Up to 3 locations", included: true },
        { text: "Up to 50 employees", included: true },
        { text: "Drag-and-drop scheduling", included: true },
        { text: "Team messaging", included: true },
        { text: "Labor compliance alerts", included: true, detail: "Basic" },
        { text: "POS integrations", included: true },
        { text: "Time clocking", included: true },
        { text: "Demand forecasting", included: false },
        { text: "Dedicated account manager", included: false },
        { text: "Support", included: true, detail: "Email & chat" },
      ],
      cta: "Start Free Trial",
      popular: true,
    },
    {
      name: "Premium",
      price: { monthly: 69.99, annual: 55.99 },
      description: "For multi-location operators who need advanced features and priority support.",
      features: [
        { text: "Unlimited locations", included: true },
        { text: "Unlimited employees", included: true },
        { text: "Drag-and-drop scheduling", included: true },
        { text: "Team messaging", included: true },
        { text: "Labor compliance alerts", included: true, detail: "Advanced" },
        { text: "POS integrations", included: true },
        { text: "Time clocking", included: true },
        { text: "Demand forecasting", included: true },
        { text: "Dedicated account manager", included: true },
        { text: "Support", included: true, detail: "Priority 24/7" },
      ],
      cta: "Start Free Trial",
      popular: false,
    },
  ],

  pricingNote: "Annual billing saves 20% on Starter and Premium plans.",

  faq: [
    {
      question: "Is there really a free plan?",
      answer: "Yes. The Free plan supports one location with up to 15 employees, no credit card required."
    },
    {
      question: "Can I switch plans at any time?",
      answer: "Absolutely. Upgrade, downgrade, or cancel anytime from your account settings."
    },
    {
      question: "Do you offer discounts for multi-location operators?",
      answer: "Yes. Contact our sales team for custom enterprise pricing on 10+ locations."
    },
    {
      question: "What happens to my data if I cancel?",
      answer: "Your data is retained for 90 days after cancellation. You can export everything at any time."
    },
    {
      question: "Is there a setup fee?",
      answer: "No. All plans include free onboarding and setup assistance."
    },
  ],

  integrations: {
    categories: [
      {
        title: "Point of Sale",
        items: ["Toast", "Square", "Clover", "Lightspeed"]
      },
      {
        title: "Payroll",
        items: ["ADP", "Gusto", "Paychex", "QuickBooks"]
      },
      {
        title: "Accounting",
        items: ["Xero", "FreshBooks", "Sage"]
      },
      {
        title: "Delivery platforms",
        items: ["DoorDash", "Uber Eats", "Grubhub"]
      },
    ]
  },

  team: [
    { name: "Rachel Nguyen", role: "CEO" },
    { name: "Marcus Webb", role: "CTO" },
    { name: "Sofia Alvarez", role: "CPO" },
    { name: "James Okafor", role: "VP of Customer Success" },
  ],

  mission: "ShiftWise was founded in 2019 by a team of former restaurant operators and software engineers who experienced the chaos of workforce management firsthand. Our mission is to empower every restaurant — from single-unit independents to national chains — with technology that makes managing people as seamless as serving guests.",

  offices: [
    { city: "San Francisco, CA", label: "HQ" },
    { city: "Austin, TX", label: "" },
    { city: "Toronto, ON", label: "" },
  ],

  contact: {
    email: "hello@shiftwise.io",
    phone: "(415) 555-0192",
    formFields: [
      { name: "fullName", label: "Full Name", type: "text", required: true },
      { name: "email", label: "Email", type: "email", required: true },
      { name: "company", label: "Company Name", type: "text", required: true },
      { name: "locations", label: "Number of Locations", type: "select", required: true, options: ["1", "2-5", "6-10", "10+"] },
      { name: "message", label: "Message", type: "textarea", required: true },
    ]
  },

  cta: {
    title: "Ready to Simplify Your Restaurant Operations?",
    subtitle: "Join 35,000+ managers who save 15 hours every week with ShiftWise.",
    cta: "Start Your Free Trial — No Credit Card Required",
  },

  footer: {
    product: ["Features", "Pricing", "Integrations", "What's New"],
    company: ["About", "Careers", "Blog", "Press"],
    support: ["Help Center", "Contact", "System Status"],
    legal: ["Privacy Policy", "Terms of Service", "Cookie Settings"],
  },

  copyright: "© 2024 ShiftWise, Inc. All rights reserved.",
}

