import React from 'react'
import { Menu, X } from 'lucide-react'
import { siteConfig } from '../config/site'

type Page = 'home' | 'features' | 'pricing' | 'about' | 'contact'

interface HeaderProps {
  currentPage: Page
  navigate: (page: Page) => void
  mobileMenuOpen: boolean
  setMobileMenuOpen: (open: boolean) => void
}

export default function Header({ currentPage, navigate, mobileMenuOpen, setMobileMenuOpen }: HeaderProps) {
  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-[#0a0a0a]/95 backdrop-blur-md border-b border-white/10">
      <nav className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <button
            onClick={() => navigate('home')}
            className="text-2xl font-bold text-white hover:text-[#FF6B35] transition-colors"
          >
            ShiftWise
          </button>

          <div className="hidden md:flex items-center gap-8">
            {siteConfig.navigation.map((item) => {
              const page = item.href.replace('.html', '') as Page
              return (
                <button
                  key={item.href}
                  onClick={() => navigate(page)}
                  className={`text-sm font-medium transition-colors ${
                    currentPage === page ? 'text-[#FF6B35]' : 'text-gray-300 hover:text-white'
                  }`}
                >
                  {item.label}
                </button>
              )
            })}
            <button
              onClick={() => navigate('pricing')}
              className="bg-[#FF6B35] hover:bg-[#ff8555] text-white px-5 py-2.5 rounded-lg font-semibold text-sm transition-all hover:scale-105"
            >
              Start Free Trial
            </button>
          </div>

          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 text-white"
          >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </nav>

      {mobileMenuOpen && (
        <div className="md:hidden bg-[#141414] border-t border-white/10">
          <div className="px-4 py-6 space-y-4">
            {siteConfig.navigation.map((item) => {
              const page = item.href.replace('.html', '') as Page
              return (
                <button
                  key={item.href}
                  onClick={() => {
                    navigate(page)
                    setMobileMenuOpen(false)
                  }}
                  className={`block w-full text-left text-lg font-medium py-2 ${
                    currentPage === page ? 'text-[#FF6B35]' : 'text-gray-300'
                  }`}
                >
                  {item.label}
                </button>
              )
            })}
            <button
              onClick={() => {
                navigate('pricing')
                setMobileMenuOpen(false)
              }}
              className="w-full bg-[#FF6B35] hover:bg-[#ff8555] text-white px-5 py-3 rounded-lg font-semibold mt-4"
            >
              Start Free Trial
            </button>
          </div>
        </div>
      )}
    </header>
  )
}

