import React, { useState } from 'react'
import { Check, X, ChevronDown, ArrowRight } from 'lucide-react'
import { siteConfig } from '../config/site'

type Page = 'home' | 'features' | 'pricing' | 'about' | 'contact'

interface PricingPageProps {
  navigate: (page: Page) => void
}

export default function PricingPage({ navigate }: PricingPageProps) {
  const [isAnnual, setIsAnnual] = useState(false)
  const [openFaq, setOpenFaq] = useState<number | null>(null)

  const toggleFaq = (index: number) => {
    setOpenFaq(openFaq === index ? null : index)
  }

  return (
    <div className="pt-16">
      {/* Hero */}
      <section className="py-24 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-[#FF6B35]/5 to-transparent" />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          <div className="text-center max-w-3xl mx-auto">
            <h1 className="text-5xl md:text-6xl font-bold text-white mb-6">
              Simple, Transparent Pricing
            </h1>
            <p className="text-xl text-gray-400 mb-8">
              Start free, scale as you grow. No hidden fees, no surprises.
            </p>

            {/* Billing Toggle */}
            <div className="inline-flex items-center gap-4 bg-[#1a1a1a] border border-white/10 rounded-full p-1.5">
              <button
                onClick={() => setIsAnnual(false)}
                className={`px-6 py-3 rounded-full font-medium transition-all ${
                  !isAnnual ? 'bg-[#FF6B35] text-white' : 'text-gray-400 hover:text-white'
                }`}
              >
                Monthly
              </button>
              <button
                onClick={() => setIsAnnual(true)}
                className={`px-6 py-3 rounded-full font-medium transition-all flex items-center gap-2 ${
                  isAnnual ? 'bg-[#FF6B35] text-white' : 'text-gray-400 hover:text-white'
                }`}
              >
                Annual
                <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">Save 20%</span>
              </button>
            </div>
          </div>
        </div>
