import React, { useState } from 'react'
import { Check, X, ChevronDown, ArrowRight } from 'lucide-react'
import { siteConfig } from '../config/site'

type Page = 'home' | 'features' | 'pricing' | 'about' | 'contact'

interface PricingPageProps {
  navigate: (page: Page) => void
}

export default function PricingPage({ navigate }: PricingPageProps) {
  const [isAnnual, setIsAnnual] = useState(false)
  const [openFaq, setOpenFaq] = useState<number | null>(null)

  const toggleFaq = (index: number) => {
    setOpenFaq(openFaq === index ? null : index)
  }

  return (
    <div className="pt-16">
      <section className="py-24 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-[#FF6B35]/5 to-transparent" />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          <div className="text-center max-w-3xl mx-auto">
            <h1 className="text-5xl md:text-6xl font-bold text-white mb-6">
              Simple, Transparent Pricing
            </h1>
            <p className="text-xl text-gray-400 mb-8">
              Start free, scale as you grow. No hidden fees, no surprises.
            </p>

            <div className="inline-flex items-center gap-4 bg-[#1a1a1a] border border-white/10 rounded-full p-1.5">
              <button
                onClick={() => setIsAnnual(false)}
                className={`px-6 py-3 rounded-full font-medium transition-all ${
                  !isAnnual ? 'bg-[#FF6B35] text-white' : 'text-gray-400 hover:text-white'
                }`}
              >
                Monthly
              </button>
              <button
                onClick={() => setIsAnnual(true)}
                className={`px-6 py-3 rounded-full font-medium transition-all flex items-center gap-2 ${
                  isAnnual ? 'bg-[#FF6B35] text-white' : 'text-gray-400 hover:text-white'
                }`}
              >
                Annual
                <span className="text-xs bg-white/20 px-2 py-0.5 rounded-full">Save 20%</span>
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="pb-24">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid md:grid-cols-3 gap-8">
            {siteConfig.pricing.map((plan, index) => (
              <div
                key={index}
                className={`relative bg-[#141414] border rounded-3xl p-8 transition-all ${
                  plan.popular
                    ? 'border-[#FF6B35] scale-105 shadow-[0_0_60px_rgba(255,107,53,0.2)]'
                    : 'border-white/10'
                }`}
              >
                {plan.popular && (
                  <div className="absolute -top-4 left-1/2 -translate-x-1/2 bg-[#FF6B35] text-white text-sm font-semibold px-4 py-1 rounded-full">
                    Most Popular
                  </div>
                )}

                <div className="text-center mb-8">
                  <h3 className="text-2xl font-bold text-white mb-2">{plan.name}</h3>
                  <p className="text-gray-400 text-sm">{plan.description}</p>
                </div>

                <div className="text-center mb-8">
                  <div className="flex items-baseline justify-center gap-1">
                    <span className="text-5xl font-bold text-white">
                      ${isAnnual ? plan.price.annual.toFixed(2) : plan.price.monthly.toFixed(2)}
                    </span>
                    <span className="text-gray-400">/mo</span>
                  </div>
                  {isAnnual && plan.price.monthly > 0 && (
                    <p className="text-gray-500 text-sm mt-2">
                      ${(plan.price.annual * 12).toFixed(2)} billed annually
                    </p>
                  )}
                </div>

                <button
                  className={`w-full py-4 rounded-xl font-semibold text-lg transition-all mb-8 ${
                    plan.popular
                      ? 'bg-[#FF6B35] hover:bg-[#ff8555] text-white'
                      : 'bg-white/10 hover:bg-white/20 text-white border border-white/20'
                  }`}
                >
                  {plan.cta}
                </button>

                <ul className="space-y-4">
                  {plan.features.map((feature, i) => (
                    <li key={i} className="flex items-start gap-3">
                      {feature.included ? (
                        <Check className="w-5 h-5 text-[#FF6B35] flex-shrink-0 mt-0.5" />
                      ) : (
                        <X className="w-5 h-5 text-gray-600 flex-shrink-0 mt-0.5" />
                      )}
                      <span className={feature.included ? 'text-gray-300' : 'text-gray-600'}>
                        {feature.text}
                        {feature.detail && (
                          <span className="text-gray-500 text-sm ml-1">({feature.detail})</span>
                        )}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>

          <p className="text-center text-gray-400 mt-8">
            {siteConfig.pricingNote}
          </p>
        </div>
      </section>

      <section className="py-24 bg-[#141414]">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <h2 className="text-4xl font-bold text-white mb-12 text-center">
            Frequently Asked Questions
          </h2>

          <div className="space-y-4">
            {siteConfig.faq.map((item, index) => (
              <div
                key={index}
                className="bg-[#1a1a1a] border border-white/10 rounded-xl overflow-hidden"
              >
                <button
                  onClick={() => toggleFaq(index)}
                  className="w-full flex items-center justify-between p-6 text-left"
                >
                  <span className="text-lg font-semibold text-white">{item.question}</span>
                  <ChevronDown
                    className={`w-5 h-5 text-gray-400 transition-transform ${
                      openFaq === index ? 'rotate-180' : ''
                    }`}
                  />
                </button>
                {openFaq === index && (
                  <div className="px-6 pb-6">
                    <p className="text-gray-400">{item.answer}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="py-24">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="bg-gradient-to-r from-[#FF6B35]/20 to-[#0051C3]/20 border border-white/10 rounded-3xl p-12 md:p-20 text-center">
            <h2 className="text-4xl md:text-5xl font-bold text-white mb-4">
              Ready to Simplify Your Restaurant Operations?
            </h2>
            <p className="text-xl text-gray-400 mb-10 max-w-2xl mx-auto">
              Join 35,000+ managers who save 15 hours every week with ShiftWise.
            </p>
            <button
              onClick={() => navigate('pricing')}
              className="bg-[#FF6B35] hover:bg-[#ff8555] text-white px-10 py-4 rounded-xl font-bold text-lg transition-all hover:scale-105 inline-flex items-center gap-2"
            >
              Start Your Free Trial — No Credit Card Required
              <ArrowRight size={20} />
            </button>
          </div>
        </div>
      </section>
    </div>
  )
}

