import React, { useState } from 'react'
import { Mail, Phone, MapPin, Send, CheckCircle } from 'lucide-react'
import { siteConfig } from '../config/site'

type Page = 'home' | 'features' | 'pricing' | 'about' | 'contact'

interface ContactPageProps {
  navigate: (page: Page) => void
}

export default function ContactPage({ navigate }: ContactPageProps) {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    company: '',
    locations: '',
    message: '',
  })
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [submitted, setSubmitted] = useState(false)

  const validateForm = () => {
    const newErrors: Record<string, string> = {}

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full Name is required'
    }
    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address'
    }
    if (!formData.company.trim()) {
      newErrors.company = 'Company Name is required'
    }
    if (!formData.locations) {
      newErrors.locations = 'Number of Locations is required'
    }
    if (!formData.message.trim()) {
      newErrors.message = 'Message is required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (validateForm()) {
      setSubmitted(true)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }))
    }
  }

  return (
    <div className="pt-16">
      <section className="py-24 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-[#FF6B35]/5 to-transparent" />
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          <div className="text-center max-w-3xl mx-auto">
            <h1 className="text-5xl md:text-6xl font-bold text-white mb-6">
              Get in Touch
            </h1>
            <p className="text-xl text-gray-400">
              Have questions or need a personalized demo? Our team will respond within one business day.
            </p>
          </div>
        </div>
      </section>

      <section className="py-24 bg-[#141414]">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-16">
            <div className="bg-[#1a1a1a] border border-white/10 rounded-3xl p-8 md:p-12">
              {submitted ? (
                <div className="text-center py-12">
                  <div className="w-20 h-20 bg-[#FF6B35]/20 rounded-full flex items-center justify-center mx-auto mb-6">
                    <CheckCircle className="w-10 h-10 text-[#FF6B35]" />
                  </div>
                  <h3 className="text-2xl font-bold text-white mb-4">Message Sent!</h3>
                  <p className="text-gray-400">
                    Thank you for reaching out. Our team will get back to you within one business day.
                  </p>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div>
                    <label htmlFor="fullName" className="block text-sm font-medium text-gray-300 mb-2">
                      Full Name *
                    </label>
                    <input
                      type="text"
                      id="fullName"
                      name="fullName"
                      value={formData.fullName}
                      onChange={handleChange}
                      className={`w-full bg-[#0a0a0a] border ${
                        errors.fullName ? 'border-red-500' : 'border-white/10'
                      } rounded-xl px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-[#FF6B35] transition-colors`}
                      placeholder="John Smith"
                    />
                    {errors.fullName && (
                      <p className="text-red-500 text-sm mt-1">{errors.fullName}</p>
                    )}
                  </div>

                  <div>
                    <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                      Email *
                    </label>
                    <input
                      type="email"
                      id="email"
                      name="email"
                      value={formData.email}
                      onChange={handleChange}
                      className={`w-full bg-[#0a0a0a] border ${
                        errors.email ? 'border-red-500' : 'border-white/10'
                      } rounded-xl px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-[#FF6B35] transition-colors`}
                      placeholder="john@restaurant.com"
                    />
                    {errors.email && (
                      <p className="text-red-500 text-sm mt-1">{errors.email}</p>
                    )}
                  </div>

                  <div>
                    <label htmlFor="company" className="block text-sm font-medium text-gray-300 mb-2">
                      Company Name *
                    </label>
                    <input
                      type="text"
                      id="company"
                      name="company"
                      value={formData.company}
                      onChange={handleChange}
                      className={`w-full bg-[#0a0a0a] border ${
                        errors.company ? 'border-red-500' : 'border-white/10'
                      } rounded-xl px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-[#FF6B35] transition-colors`}
                      placeholder="Fuego Kitchen"
                    />
                    {errors.company && (
                      <p className="text-red-500 text-sm mt-1">{errors.company}</p>
                    )}
                  </div>

                  <div>
                    <label htmlFor="locations" className="block text-sm font-medium text-gray-300 mb-2">
                      Number of Locations *
                    </label>
                    <select
                      id="locations"
                      name="locations"
                      value={formData.locations}
                      onChange={handleChange}
                      className={`w-full bg-[#0a0a0a] border ${
                        errors.locations ? 'border-red-500' : 'border-white/10'
                      } rounded-xl px-4 py-3 text-white focus:outline-none focus:border-[#FF6B35] transition-colors`}
                    >
                      <option value="" className="text-gray-500">Select...</option>
                      {siteConfig.contact.formFields[3].options?.map((option) => (
                        <option key={option} value={option} className="text-white">
                          {option}
                        </option>
                      ))}
                    </select>
                    {errors.locations && (
                      <p className="text-red-500 text-sm mt-1">{errors.locations}</p>
                    )}
                  </div>

                  <div>
                    <label htmlFor="message" className="block text-sm font-medium text-gray-300 mb-2">
                      Message *
                    </label>
                    <textarea
                      id="message"
                      name="message"
                      value={formData.message}
                      onChange={handleChange}
                      rows={5}
                      className={`w-full bg-[#0a0a0a] border ${
                        errors.message ? 'border-red-500' : 'border-white/10'
                      } rounded-xl px-4 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-[#FF6B35] transition-colors resize-none`}
                      placeholder="Tell us about your restaurant and how we can help..."
                    />
                    {errors.message && (
                      <p className="text-red-500 text-sm mt-1">{errors.message}</p>
                    )}
                  </div>

                  <button
                    type="submit"
                    className="w-full bg-[#FF6B35] hover:bg-[#ff8555] text-white px-8 py-4 rounded-xl font-semibold text-lg transition-all hover:scale-[1.02] flex items-center justify-center gap-2"
                  >
                    Send Message
                    <Send size={20} />
                  </button>
                </form>
              )}
            </div>

            <div className="space-y-8">
              <div>
                <h2 className="text-3xl font-bold text-white mb-8">
                  Contact Information
                </h2>
                <div className="space-y-6">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-[#FF6B35]/20 rounded-xl flex items-center justify-center">
                      <Mail className="w-6 h-6 text-[#FF6B35]" />
                    </div>
                    <div>
                      <p className="text-gray-400 text-sm">Email</p>
                      <p className="text-white font-medium">{siteConfig.contact.email}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-[#FF6B35]/20 rounded-xl flex items-center justify-center">
                      <Phone className="w-6 h-6 text-[#FF6B35]" />
                    </div>
                    <div>
                      <p className="text-gray-400 text-sm">Phone</p>
                      <p className="text-white font-medium">{siteConfig.contact.phone}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-[#1a1a1a] border border-white/10 rounded-2xl p-8">
                <h3 className="text-xl font-bold text-white mb-6">Our Offices</h3>
                <div className="space-y-4">
                  {siteConfig.offices.map((office, index) => (
                    <div key={index} className="flex items-center gap-4">
                      <MapPin className="w-5 h-5 text-[#FF6B35]" />
                      <div>
                        <p className="text-white">{office.city}</p>
                        {office.label && (
                          <p className="text-[#FF6B35] text-sm">{office.label}</p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-gradient-to-r from-[#FF6B35]/20 to-[#0051C3]/20 border border-white/10 rounded-2xl p-8">
                <h3 className="text-xl font-bold text-white mb-4">Need Immediate Help?</h3>
                <p className="text-gray-400 mb-6">
                  Check our Help Center for quick answers to common questions.
                </p>
                <button className="bg-white/10 hover:bg-white/20 text-white px-6 py-3 rounded-xl font-medium transition-all">
                  Visit Help Center
                </button>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  )
}
